import{_ as e,a0 as p,w as r,s as a,ao as i,I as o,x as u,a1 as s,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在双启动或单启动模式下重新安装 Ubuntu | LCTT x X-CMD","titleTemplate":false,"description":"如何在双启动或单启动模式下重新安装 Ubuntu | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在双启动或单启动模式下重新安装 Ubuntu | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在双启动或单启动模式下重新安装 Ubuntu | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190814 How to Reinstall Ubuntu in Dual Boot or Single Boot Mode","title":"如何在双启动或单启动模式下重新安装 Ubuntu","tag":"201908","desc":""},"relativePath":"201908/20190814 How to Reinstall Ubuntu in Dual Boot or Single Boot Mode.md","filePath":"[post].md"}'),b={name:"201908/20190814 How to Reinstall Ubuntu in Dual Boot or Single Boot Mode.md"};function d(U,t,m,f,T,g){const n=p("Link");return r(),a("div",null,[t[25]||(t[25]=i('<h1 id="如何在双启动或单启动模式下重新安装-ubuntu" tabindex="-1">如何在双启动或单启动模式下重新安装 Ubuntu <a class="header-anchor" href="#如何在双启动或单启动模式下重新安装-ubuntu" aria-label="Permalink to “如何在双启动或单启动模式下重新安装 Ubuntu”">​</a></h1><p>如果你弄坏了你的 Ubuntu 系统，并尝试了很多方法来修复，你最终放弃并采取简单的方法：重新安装 Ubuntu。</p><p>我们一直遇到这样一种情况，重新安装 Linux 似乎比找出问题并解决来得更好。排查 Linux 故障能教你很多，但你不会总是花费更多时间来修复损坏的系统。</p><p>据我所知，Ubuntu 中没有像 Windows 那样的系统恢复分区。那么，问题出现了：如何重新安装 Ubuntu？让我告诉你如何重新安装 Ubuntu。</p><p><strong>警告！</strong></p><blockquote><p><strong>磁盘分区始终是一项危险的任务。我强烈建议你在外部磁盘上备份数据。</strong></p></blockquote><h3 id="如何重新安装-ubuntu-linux" tabindex="-1">如何重新安装 Ubuntu Linux <a class="header-anchor" href="#如何重新安装-ubuntu-linux" aria-label="Permalink to “如何重新安装 Ubuntu Linux”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/08/Reinstall-Ubuntu.png?resize=800%2C450&amp;ssl=1" alt=""></p><p>以下是重新安装 Ubuntu 的步骤。</p><h4 id="步骤-1-创建一个-live-usb" tabindex="-1">步骤 1：创建一个 live USB <a class="header-anchor" href="#步骤-1-创建一个-live-usb" aria-label="Permalink to “步骤 1：创建一个 live USB”">​</a></h4>',10)),o("p",null,[t[1]||(t[1]=u("首先，在网站上下载 Ubuntu。你可以下载",-1)),s(n,{href:"https://itsfoss.com/which-ubuntu-install/"},{default:l(()=>[...t[0]||(t[0]=[u("任何需要的 Ubuntu 版本",-1)])]),_:1}),t[2]||(t[2]=u("。",-1))]),o("ul",null,[o("li",null,[s(n,{href:"https://ubuntu.com/download/desktop"},{default:l(()=>[...t[3]||(t[3]=[u("下载 Ubuntu",-1)])]),_:1})])]),t[26]||(t[26]=o("p",null,"获得 ISO 镜像后，就可以创建 live USB 了。如果 Ubuntu 系统仍然可以使用，那么可以使用 Ubuntu 提供的启动盘创建工具创建它。",-1)),o("p",null,[t[5]||(t[5]=u("如果无法使用你的 Ubuntu，那么你可以使用其他系统。你可以参考这篇文章来学习",-1)),s(n,{href:"https://itsfoss.com/create-live-usb-of-ubuntu-in-windows/"},{default:l(()=>[...t[4]||(t[4]=[u("如何在 Windows 中创建 Ubuntu 的 live USB",-1)])]),_:1}),t[6]||(t[6]=u("。",-1))]),t[27]||(t[27]=i('<h4 id="步骤-2-重新安装-ubuntu" tabindex="-1">步骤 2：重新安装 Ubuntu <a class="header-anchor" href="#步骤-2-重新安装-ubuntu" aria-label="Permalink to “步骤 2：重新安装 Ubuntu”">​</a></h4><p>有了 Ubuntu 的 live USB 之后将其插入 USB 端口。重新启动系统。在启动时，按下 <code>F2</code>/<code>F10</code>/<code>F12</code> 之类的键进入 BIOS 设置，并确保已设置 “Boot from Removable Devices/USB”。保存并退出 BIOS。这将启动进入 live USB。</p><p>进入 live USB 后，选择安装 Ubuntu。你将看到选择语言和键盘布局这些常用选项。你还可以选择下载更新等。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/08/reinstall-ubuntu-1.jpg?resize=800%2C473&amp;ssl=1" alt="Go ahead with regular installation option"></p><p>现在是重要的步骤。你应该看到一个“<ruby>安装类型<rt>Installation Type</rt></ruby>”页面。你在屏幕上看到的内容在很大程度上取决于 Ubuntu 如何处理系统上的磁盘分区和安装的操作系统。</p><p>在此步骤中仔细阅读选项及它的细节。注意每个选项的说明。屏幕上的选项可能在不同的系统中看上去不同。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/08/reinstall-ubuntu-dual-boot.jpg?ssl=1" alt="Reinstall Ubuntu option in dual boot mode"></p><p>在这里，它发现我的系统上安装了 Ubuntu 18.04.2 和 Windows，它给了我一些选项。</p><p>第一个选项是擦除 Ubuntu 18.04.2 并重新安装它。它告诉我它将删除我的个人数据，但它没有说删除所有操作系统（即 Windows）。</p><p>如果你非常幸运或处于单一启动模式，你可能会看到一个“<ruby>重新安装 Ubuntu<rt>Reinstall Ubuntu</rt></ruby>”的选项。此选项将保留现有数据，甚至尝试保留已安装的软件。如果你看到这个选项，那么就用它吧。</p><p><strong>双启动系统注意</strong></p>',11)),o("blockquote",null,[o("p",null,[o("strong",null,[t[8]||(t[8]=u("如果你是双启动 Ubuntu 和 Windows，并且在重新安装中，你的 Ubuntu 系统看不到 Windows，你必须选择 “Something else” 选项并从那里安装 Ubuntu。我已经在",-1)),s(n,{href:"https://itsfoss.com/replace-linux-from-dual-boot/"},{default:l(()=>[...t[7]||(t[7]=[u("在双启动下安装 Linux 的过程",-1)])]),_:1}),t[9]||(t[9]=u("这篇文章中说明了。",-1))])])]),t[28]||(t[28]=i('<p>对我来说，没有重新安装并保留数据的选项，因此我选择了“<ruby>擦除 Ubuntu 并重新安装<rt>Erase Ubuntu and reinstall</rt></ruby>”。该选项即使在 Windows 的双启动模式下，也将重新安装 Ubuntu。</p><p>我建议为 <code>/</code> 和 <code>/home</code> 使用单独分区就是为了重新安装。这样，即使重新安装 Linux，也可以保证 <code>/home</code> 分区中的数据安全。我已在此视频中演示过：</p><p>选择重新安装 Ubuntu 后，剩下就是单击下一步。选择你的位置、创建用户账户。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/08/reinstall-ubuntu-3.jpg?ssl=1" alt="Just go on with the installation options"></p><p>以上完成后，你就完成重装 Ubuntu 了。</p><p>在本教程中，我假设你已经知道我说的东西，因为你之前已经安装过 Ubuntu。如果需要澄清任何一个步骤，请随时在评论栏询问。</p><hr>',7)),o("p",null,[t[11]||(t[11]=u("via: ",-1)),s(n,{href:"https://itsfoss.com/reinstall-ubuntu/"},{default:l(()=>[...t[10]||(t[10]=[u("https://itsfoss.com/reinstall-ubuntu/",-1)])]),_:1})]),o("p",null,[t[16]||(t[16]=u("作者：",-1)),s(n,{href:"https://itsfoss.com/author/abhishek/"},{default:l(()=>[...t[12]||(t[12]=[u("Abhishek Prakash",-1)])]),_:1}),t[17]||(t[17]=u(" 选题：",-1)),s(n,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[13]||(t[13]=[u("lujun9972",-1)])]),_:1}),t[18]||(t[18]=u(" 译者：",-1)),s(n,{href:"https://github.com/geekpi"},{default:l(()=>[...t[14]||(t[14]=[u("geekpi",-1)])]),_:1}),t[19]||(t[19]=u(" 校对：",-1)),s(n,{href:"https://github.com/wxy"},{default:l(()=>[...t[15]||(t[15]=[u("wxy",-1)])]),_:1})]),o("p",null,[t[22]||(t[22]=u("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[20]||(t[20]=[u("LCTT",-1)])]),_:1}),t[23]||(t[23]=u(" 原创编译，",-1)),s(n,{href:"https://linux.cn/"},{default:l(()=>[...t[21]||(t[21]=[u("Linux中国",-1)])]),_:1}),t[24]||(t[24]=u(" 荣誉推出",-1))])])}const B=e(b,[["render",d]]);export{x as __pageData,B as default};
